document.addEventListener('DOMContentLoaded',()=>{
const $=id=>document.getElementById(id), widget=$('pde-chat-widget'), launcher=$('pde-chat-launcher'), box=$('pde-chat-messages'), input=$('pde-chat-input');
if(!widget||!launcher)return;
function message(text,user=false){const el=document.createElement('div');el.className='pde-message '+(user?'pde-user-message':'pde-bot-message');el.textContent=text;box.append(el);box.scrollTop=box.scrollHeight}
function actions(){const wrap=$('pde-chat-quick-actions');wrap.replaceChildren();for(const label of ['Courses','Healing Services','Book Consultation','WhatsApp Support']){const b=document.createElement('button');b.type='button';b.className='pde-quick-action';b.textContent=label;b.onclick=()=>reply(label);wrap.append(b)}}
function reply(text){message(text,true);const q=text.toLowerCase();if(q.includes('whatsapp')){const a=document.createElement('a');a.href='https://wa.me/917691011395';a.textContent='Open WhatsApp support';a.className='pde-message pde-bot-message';box.append(a)}else if(/book|consult|callback/.test(q)){message('Please share your details below. Your email app will open with a callback request for you to send.');$('pde-chat-lead-form')?.classList.remove('pde-hidden')}else if(/course|reiki|master|prana/.test(q)){message('Explore Reiki Level 1 (₹5,111), Reiki Level 2 (₹7,111), Master & Teacher (₹15,111), Grandmaster (₹21,511), Basic Colour Prana (₹7,111), and Advance Prana Energy (₹9,999). Visit Courses to see the full learning paths.')}else if(/healing|chakra|aura|service/.test(q)){message('Our services include distance healing, personal spiritual guidance, chakra balancing and aura cleansing. Contact Jyotsana Ji to discuss a session.')}else{message('This guided assistant can help with courses, healing services and consultations. For a personal answer, contact hello@puredivineenergy.com or +91 7691011395.')}actions()}
launcher.onclick=()=>{widget.classList.remove('pde-hidden');launcher.classList.add('pde-hidden');if(!box.dataset.welcomed){message('Welcome to Pure Divine Energy. Explore our courses, healing services, or request a consultation.');actions();box.dataset.welcomed='true'}input.focus()};
$('pde-chat-close').onclick=()=>{widget.classList.add('pde-hidden');launcher.classList.remove('pde-hidden');launcher.focus()};
function send(){const t=input.value.trim();if(t){input.value='';reply(t)}}$('pde-chat-send').onclick=send;input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();send()}if(e.key==='Escape')$('pde-chat-close').click()};
$('pde-chat-lead-form')?.addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const body=`Name: ${$('pde-lead-name').value}\nEmail: ${$('pde-lead-email').value}\nPhone: ${$('pde-lead-phone').value}\nPlease contact me for a healing consultation.`;location.href='mailto:hello@puredivineenergy.com?subject=Consultation%20request&body='+encodeURIComponent(body);message('Your email app will open. Please send your request there.');});
});
